// Imports the local, data-only model interchange generated by .3d-model/tools.
// Source models and textures remain outside Assets; all Unity assets are copies.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace Manosaba.EditorTools
{
    public static class PrototypeModelImporter
    {
        private const string ModelAssetRoot = "Assets/ThreeDPrototype/Models";
        private const string TextureShader = "Manosaba/Prototype Textured";
        private const string LitShader = "Manosaba/Prototype Lit";
        private static readonly StringComparison PathComparison =
            Application.platform == RuntimePlatform.WindowsEditor
                ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;

        /// <summary>
        /// Imports the sole *.model.json in sourceDir. targetDir is either an
        /// Assets path or an absolute path beneath Assets/ThreeDPrototype/Models.
        /// The source folder name determines the prefab name (Ema or BMPT72).
        /// Returns the saved prefab asset, not a scene instance.
        /// </summary>
        public static GameObject Import(string sourceDir, string targetDir)
        {
            var project = Directory.GetParent(Application.dataPath).FullName;
            var source = AbsolutePath(sourceDir, project);
            var target = AbsolutePath(targetDir, project);
            var outputRoot = Path.GetFullPath(Path.Combine(project, ModelAssetRoot));
            if (!Directory.Exists(source)) throw new DirectoryNotFoundException(source);
            RequireWithin(target, outputRoot, "Model output", true);
            if (IsWithin(target, source, true) || IsWithin(source, target, true))
                throw new InvalidDataException("Source and Unity output folders must be separate.");
            RejectLinks(source, source);
            RejectLinks(target, project);

            var files = Directory.GetFiles(source, "*.model.json", SearchOption.TopDirectoryOnly);
            if (files.Length != 1)
                throw new InvalidDataException("Expected exactly one *.model.json in " + source);
            RejectLinks(files[0], source);
            if (new FileInfo(files[0]).Length > 512L * 1024 * 1024)
                throw new InvalidDataException("Model JSON exceeds the 512 MiB import limit.");

            ModelData data;
            using (var stream = File.OpenText(files[0]))
            using (var reader = new JsonTextReader(stream) { MaxDepth = 64, DateParseHandling = DateParseHandling.None })
            {
                var serializer = JsonSerializer.Create(new JsonSerializerSettings {
                    TypeNameHandling = TypeNameHandling.None,
                    MetadataPropertyHandling = MetadataPropertyHandling.Ignore
                });
                data = serializer.Deserialize<ModelData>(reader);
            }
            Validate(data, source);

            var assetDir = "Assets/" + target.Substring(Application.dataPath.Length)
                .TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar).Replace('\\', '/');
            var modelName = SafeName(new DirectoryInfo(source).Name);
            Directory.CreateDirectory(target);
            Directory.CreateDirectory(Path.Combine(target, "Textures"));
            Directory.CreateDirectory(Path.Combine(target, "Materials"));
            Directory.CreateDirectory(Path.Combine(target, "Meshes"));
            AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);

            var textureCache = new Dictionary<string, Texture2D>(StringComparer.OrdinalIgnoreCase);
            var materials = new Material[data.materials.Length];
            for (int i = 0; i < materials.Length; i++)
                materials[i] = ImportMaterial(data.materials[i], i, source, assetDir, modelName, textureCache);

            var root = new GameObject(modelName);
            try
            {
                var transforms = new Transform[data.nodes.Length];
                for (int i = 0; i < transforms.Length; i++)
                    transforms[i] = new GameObject(NodeName(data.nodes[i].name, "Node_" + i)).transform;
                // Set every parent before assigning local TRS; parents need not precede children.
                for (int i = 0; i < transforms.Length; i++)
                    transforms[i].SetParent(data.nodes[i].parent < 0 ? root.transform : transforms[data.nodes[i].parent], false);
                for (int i = 0; i < transforms.Length; i++)
                {
                    var node = data.nodes[i];
                    transforms[i].localPosition = Vector3At(node.position, 0);
                    var rotation = new Quaternion(node.rotation[0], node.rotation[1], node.rotation[2], node.rotation[3]);
                    transforms[i].localRotation = rotation.normalized;
                    transforms[i].localScale = Vector3At(node.scale, 0);
                }

                bool hasSkin = false;
                for (int i = 0; i < data.meshes.Length; i++)
                {
                    var sourceMesh = data.meshes[i];
                    var child = new GameObject(NodeName(sourceMesh.name, "Mesh_" + i));
                    child.transform.SetParent(transforms[sourceMesh.node], false);
                    var mesh = BuildMesh(sourceMesh);
                    mesh.name = NodeName(sourceMesh.name, modelName + "_Mesh_" + i);
                    var path = assetDir + "/Meshes/" + i.ToString("D4") + ".asset";
                    mesh = SaveMesh(mesh, path);
                    var assignedMaterials = sourceMesh.submeshes.Select(s => materials[s.material]).ToArray();
                    if (sourceMesh.bones.Length > 0)
                    {
                        hasSkin = true;
                        var renderer = child.AddComponent<SkinnedMeshRenderer>();
                        var bones = sourceMesh.bones.Select(index => transforms[index]).ToArray();
                        mesh.bindposes = bones.Select(b => b.worldToLocalMatrix * child.transform.localToWorldMatrix).ToArray();
                        EditorUtility.SetDirty(mesh);
                        renderer.sharedMesh = mesh;
                        renderer.bones = bones;
                        renderer.rootBone = CommonAncestor(bones, root.transform);
                        renderer.sharedMaterials = assignedMaterials;
                        renderer.updateWhenOffscreen = true;
                        renderer.quality = SkinQuality.Bone4;
                        renderer.localBounds = new Bounds(mesh.bounds.center, mesh.bounds.size + Vector3.one * 0.4f);
                        renderer.shadowCastingMode = ShadowCastingMode.TwoSided;
                    }
                    else
                    {
                        child.AddComponent<MeshFilter>().sharedMesh = mesh;
                        var renderer = child.AddComponent<MeshRenderer>();
                        renderer.sharedMaterials = assignedMaterials;
                        renderer.shadowCastingMode = ShadowCastingMode.TwoSided;
                    }
                }
                if (hasSkin) root.AddComponent<Animator>().applyRootMotion = false;
                AssetDatabase.SaveAssets();
                var prefabPath = assetDir + "/" + modelName + ".prefab";
                var prefab = PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
                if (!prefab) throw new IOException("Failed to save " + prefabPath);
                Debug.Log("[3D prototype] Imported " + prefabPath + ": " + data.nodes.Length +
                    " nodes, " + data.meshes.Length + " meshes, " + data.meshes.Sum(m => m.morphs.Length) + " morphs.");
                return prefab;
            }
            finally { UnityEngine.Object.DestroyImmediate(root); }
        }

        private static Material ImportMaterial(MaterialData data, int index, string source, string assetDir,
            string modelName, Dictionary<string, Texture2D> cache)
        {
            bool useTextureShader = modelName.Equals("Ema", StringComparison.OrdinalIgnoreCase);
            var shader = Shader.Find(useTextureShader ? TextureShader : LitShader);
            if (!shader) throw new InvalidOperationException("Required prototype shader was not found.");
            var path = assetDir + "/Materials/" + index.ToString("D4") + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (!material)
            {
                if (AssetDatabase.LoadMainAssetAtPath(path)) throw new IOException("Asset is not a material: " + path);
                material = new Material(shader);
                AssetDatabase.CreateAsset(material, path);
            }
            material.shader = shader;
            material.shaderKeywords = Array.Empty<string>();
            material.name = NodeName(data.name, "Material_" + index);
            var color = new Color(data.color[0], data.color[1], data.color[2], data.color[3]);
            material.SetColor("_Color", color);
            Texture2D texture = null;
            if (!string.IsNullOrEmpty(data.texture))
            {
                var sourcePath = SourceTexturePath(source, data.texture);
                if (!cache.TryGetValue(sourcePath, out texture))
                {
                    var textureAsset = assetDir + "/Textures/" + cache.Count.ToString("D4") + "_" + SafeName(Path.GetFileName(sourcePath));
                    var textureFile = Path.Combine(Directory.GetParent(Application.dataPath).FullName, textureAsset);
                    File.Copy(sourcePath, textureFile, true);
                    AssetDatabase.ImportAsset(textureAsset, ImportAssetOptions.ForceSynchronousImport | ImportAssetOptions.ForceUpdate);
                    var importer = AssetImporter.GetAtPath(textureAsset) as TextureImporter;
                    if (!importer) throw new InvalidDataException("Not a supported texture: " + data.texture);
                    importer.textureType = TextureImporterType.Default;
                    importer.sRGBTexture = true;
                    importer.mipmapEnabled = true;
                    importer.alphaSource = TextureImporterAlphaSource.FromInput;
                    importer.alphaIsTransparency = true;
                    importer.wrapMode = TextureWrapMode.Repeat;
                    importer.filterMode = FilterMode.Bilinear;
                    importer.textureCompression = TextureImporterCompression.Uncompressed;
                    importer.maxTextureSize = 8192;
                    importer.SaveAndReimport();
                    texture = AssetDatabase.LoadAssetAtPath<Texture2D>(textureAsset);
                    if (!texture) throw new InvalidDataException("Texture import failed: " + data.texture);
                    cache.Add(sourcePath, texture);
                }
            }
            material.SetTexture("_MainTex", texture);
            bool transparent = color.a < 0.999f;
            bool clip = data.alpha && !transparent;
            material.SetOverrideTag("RenderType", transparent ? "Transparent" : clip ? "TransparentCutout" : "Opaque");
            material.renderQueue = transparent ? (int)RenderQueue.Transparent : clip ? (int)RenderQueue.AlphaTest : -1;
            material.SetInt("_SrcBlend", (int)(transparent ? BlendMode.SrcAlpha : BlendMode.One));
            material.SetInt("_DstBlend", (int)(transparent ? BlendMode.OneMinusSrcAlpha : BlendMode.Zero));
            material.SetInt("_ZWrite", transparent ? 0 : 1);
            material.SetFloat("_Cutoff", 0.35f);
            material.SetFloat("_AlphaClip", clip ? 1 : 0);
            material.SetInt("_Cull", (int)(data.doubleSided ? CullMode.Off : CullMode.Back));
            if (!useTextureShader)
            {
                material.SetFloat("_Glossiness", 0.15f);
                material.SetFloat("_Metallic", 0.05f);
            }
            material.doubleSidedGI = data.doubleSided;
            EditorUtility.SetDirty(material);
            return material;
        }

        private static Mesh BuildMesh(MeshData data)
        {
            int count = data.vertices.Length / 3;
            var mesh = new Mesh { indexFormat = count > 65535 ? IndexFormat.UInt32 : IndexFormat.UInt16 };
            mesh.vertices = Vectors(data.vertices);
            if (data.normals.Length > 0) mesh.normals = Vectors(data.normals);
            if (data.uv.Length > 0)
            {
                var uv = new Vector2[count];
                for (int i = 0; i < count; i++) uv[i] = new Vector2(data.uv[i * 2], data.uv[i * 2 + 1]);
                mesh.uv = uv;
            }
            mesh.subMeshCount = data.submeshes.Length;
            for (int i = 0; i < data.submeshes.Length; i++) mesh.SetTriangles(data.submeshes[i].indices, i, false);
            if (data.normals.Length == 0) mesh.RecalculateNormals();
            if (data.bones.Length > 0)
            {
                var weights = new BoneWeight[count];
                for (int i = 0; i < count; i++)
                {
                    int offset = i * 4;
                    float sum = data.weights[offset] + data.weights[offset + 1] + data.weights[offset + 2] + data.weights[offset + 3];
                    weights[i] = new BoneWeight {
                        boneIndex0 = Math.Max(0, data.boneIndices[offset]),
                        boneIndex1 = Math.Max(0, data.boneIndices[offset + 1]),
                        boneIndex2 = Math.Max(0, data.boneIndices[offset + 2]),
                        boneIndex3 = Math.Max(0, data.boneIndices[offset + 3]),
                        weight0 = sum > 0 ? data.weights[offset] / sum : 1,
                        weight1 = sum > 0 ? data.weights[offset + 1] / sum : 0,
                        weight2 = sum > 0 ? data.weights[offset + 2] / sum : 0,
                        weight3 = sum > 0 ? data.weights[offset + 3] / sum : 0
                    };
                }
                mesh.boneWeights = weights;
            }
            var names = new HashSet<string>(StringComparer.Ordinal);
            for (int i = 0; i < data.morphs.Length; i++)
            {
                var morph = data.morphs[i];
                var name = NodeName(morph.name, "Morph_" + i);
                while (!names.Add(name)) name += "_" + i;
                var offsets = new Vector3[count];
                for (int j = 0; j < morph.indices.Length; j++) offsets[morph.indices[j]] += Vector3At(morph.offsets, j * 3);
                mesh.AddBlendShapeFrame(name, 100, offsets, null, null);
            }
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh SaveMesh(Mesh mesh, string path)
        {
            var existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing)
            {
                EditorUtility.CopySerialized(mesh, existing);
                UnityEngine.Object.DestroyImmediate(mesh);
                EditorUtility.SetDirty(existing);
                return existing;
            }
            if (AssetDatabase.LoadMainAssetAtPath(path)) throw new IOException("Asset is not a mesh: " + path);
            AssetDatabase.CreateAsset(mesh, path);
            return mesh;
        }

        private static void Validate(ModelData data, string source)
        {
            if (data == null || data.nodes == null || data.nodes.Length == 0 || data.materials == null || data.meshes == null)
                throw new InvalidDataException("Model needs nodes, materials and meshes arrays.");
            for (int i = 0; i < data.nodes.Length; i++)
            {
                var node = data.nodes[i];
                if (node == null || node.parent < -1 || node.parent >= data.nodes.Length) Fail("Invalid node parent.");
                CheckFloats(node.position, 3, "position"); CheckFloats(node.rotation, 4, "rotation"); CheckFloats(node.scale, 3, "scale");
                if (node.rotation.All(v => Math.Abs(v) < 1e-8f)) Fail("Zero node quaternion.");
                int ancestor = i, depth = 0;
                while (ancestor >= 0)
                {
                    if (++depth > data.nodes.Length) Fail("Node hierarchy contains a cycle.");
                    ancestor = data.nodes[ancestor].parent;
                    if (ancestor < -1 || ancestor >= data.nodes.Length) Fail("Invalid node ancestor.");
                }
            }
            foreach (var material in data.materials)
            {
                if (material == null) Fail("Null material.");
                CheckFloats(material.color, 4, "material color");
                if (!string.IsNullOrEmpty(material.texture)) SourceTexturePath(source, material.texture);
            }
            foreach (var mesh in data.meshes)
            {
                if (mesh == null || mesh.vertices == null || mesh.vertices.Length == 0 || mesh.vertices.Length % 3 != 0) Fail("Invalid vertices.");
                int count = mesh.vertices.Length / 3;
                CheckFloats(mesh.vertices, count * 3, "vertices");
                if (mesh.node < 0 || mesh.node >= data.nodes.Length) Fail("Invalid mesh node.");
                if (mesh.normals == null || mesh.uv == null || mesh.bones == null || mesh.morphs == null || mesh.submeshes == null || mesh.submeshes.Length == 0)
                    Fail("Invalid mesh arrays.");
                if (mesh.normals.Length > 0) CheckFloats(mesh.normals, count * 3, "normals");
                if (mesh.uv.Length > 0) CheckFloats(mesh.uv, count * 2, "UVs");
                foreach (var submesh in mesh.submeshes)
                {
                    if (submesh == null || submesh.material < 0 || submesh.material >= data.materials.Length || submesh.indices == null || submesh.indices.Length % 3 != 0)
                        Fail("Invalid submesh.");
                    CheckIndices(submesh.indices, count, "triangle");
                }
                CheckIndices(mesh.bones, data.nodes.Length, "bone");
                if (mesh.bones.Length > 0)
                {
                    CheckFloats(mesh.weights, count * 4, "skin weights");
                    if (mesh.boneIndices == null || mesh.boneIndices.Length != count * 4) Fail("Invalid skin bone indices.");
                    for (int i = 0; i < mesh.weights.Length; i++)
                    {
                        if (mesh.weights[i] < 0) Fail("Negative skin weight.");
                        if (mesh.weights[i] > 0 && (mesh.boneIndices[i] < 0 || mesh.boneIndices[i] >= mesh.bones.Length)) Fail("Skin bone index outside palette.");
                        if (mesh.weights[i] == 0) mesh.boneIndices[i] = 0;
                    }
                }
                foreach (var morph in mesh.morphs)
                {
                    if (morph == null || morph.indices == null) Fail("Invalid morph.");
                    CheckIndices(morph.indices, count, "morph");
                    CheckFloats(morph.offsets, morph.indices.Length * 3, "morph offsets");
                }
            }
        }

        private static string SourceTexturePath(string source, string relative)
        {
            if (Path.IsPathRooted(relative) || relative.IndexOf(':') >= 0) Fail("Texture paths must be relative.");
            var path = Path.GetFullPath(Path.Combine(source, relative.Replace('/', Path.DirectorySeparatorChar)));
            RequireWithin(path, source, "Texture", false);
            RejectLinks(path, source);
            if (!File.Exists(path)) throw new FileNotFoundException("Missing model texture.", path);
            var extension = Path.GetExtension(path).ToLowerInvariant();
            if (!new[] { ".png", ".jpg", ".jpeg", ".tga", ".bmp", ".dds", ".psd", ".tif", ".tiff" }.Contains(extension))
                Fail("Unsupported model texture extension: " + extension);
            return path;
        }

        private static string AbsolutePath(string path, string project)
        {
            if (string.IsNullOrWhiteSpace(path)) throw new ArgumentException("An import path is required.");
            return Path.GetFullPath(Path.IsPathRooted(path) ? path : Path.Combine(project, path))
                .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        }
        private static bool IsWithin(string path, string root, bool allowRoot)
        {
            return (allowRoot && path.Equals(root, PathComparison)) || path.StartsWith(root + Path.DirectorySeparatorChar, PathComparison);
        }
        private static void RequireWithin(string path, string root, string label, bool allowRoot)
        {
            if (!IsWithin(path, root, allowRoot)) throw new InvalidDataException(label + " is outside its allowed folder.");
        }
        private static void RejectLinks(string path, string boundary)
        {
            for (var current = path; IsWithin(current, boundary, true); current = Path.GetDirectoryName(current))
            {
                if ((File.Exists(current) || Directory.Exists(current)) && (File.GetAttributes(current) & FileAttributes.ReparsePoint) != 0)
                    throw new InvalidDataException("Linked import paths are not supported: " + current);
                if (current.Equals(boundary, PathComparison)) break;
            }
        }
        private static void CheckFloats(float[] values, int length, string label)
        {
            if (values == null || values.Length != length || values.Any(v => float.IsNaN(v) || float.IsInfinity(v))) Fail("Invalid " + label + ".");
        }
        private static void CheckIndices(int[] indices, int count, string label)
        {
            if (indices.Any(i => i < 0 || i >= count)) Fail("Invalid " + label + " index.");
        }
        private static Vector3 Vector3At(float[] values, int offset) { return new Vector3(values[offset], values[offset + 1], values[offset + 2]); }
        private static Vector3[] Vectors(float[] values)
        {
            var result = new Vector3[values.Length / 3];
            for (int i = 0; i < result.Length; i++) result[i] = Vector3At(values, i * 3);
            return result;
        }
        private static Transform CommonAncestor(Transform[] bones, Transform fallback)
        {
            for (var candidate = bones[0]; candidate; candidate = candidate.parent)
                if (bones.All(b => b == candidate || b.IsChildOf(candidate))) return candidate;
            return fallback;
        }
        private static string NodeName(string value, string fallback) { return string.IsNullOrWhiteSpace(value) ? fallback : value; }
        private static string SafeName(string value)
        {
            var invalid = Path.GetInvalidFileNameChars();
            var safe = new string(value.Select(c => invalid.Contains(c) ? '_' : c).ToArray()).Trim().Trim('.');
            return string.IsNullOrEmpty(safe) ? "Model" : safe;
        }
        private static void Fail(string message) { throw new InvalidDataException(message); }

        [Serializable] private sealed class ModelData
        {
            public NodeData[] nodes = Array.Empty<NodeData>();
            public MaterialData[] materials = Array.Empty<MaterialData>();
            public MeshData[] meshes = Array.Empty<MeshData>();
        }
        [Serializable] private sealed class NodeData
        {
            public string name;
            public int parent = -1;
            public float[] position = { 0, 0, 0 };
            public float[] rotation = { 0, 0, 0, 1 };
            public float[] scale = { 1, 1, 1 };
        }
        [Serializable] private sealed class MaterialData
        {
            public string name;
            public float[] color = { 1, 1, 1, 1 };
            public string texture;
            public bool doubleSided;
            public bool alpha;
        }
        [Serializable] private sealed class MeshData
        {
            public string name;
            public int node;
            public float[] vertices = Array.Empty<float>();
            public float[] normals = Array.Empty<float>();
            public float[] uv = Array.Empty<float>();
            public SubmeshData[] submeshes = Array.Empty<SubmeshData>();
            public int[] bones = Array.Empty<int>();
            public float[] weights = Array.Empty<float>();
            public int[] boneIndices = Array.Empty<int>();
            public MorphData[] morphs = Array.Empty<MorphData>();
        }
        [Serializable] private sealed class SubmeshData { public int material; public int[] indices = Array.Empty<int>(); }
        [Serializable] private sealed class MorphData { public string name; public int[] indices = Array.Empty<int>(); public float[] offsets = Array.Empty<float>(); }
    }
}
